const listCreditSources = `-- name: ListCreditSources :many
SELECT s.id, s.kind, s.credits AS granted, s.expires_at, s.created_at, s.plan,
       (s.credits + COALESCE(u.used, 0))::integer AS remaining,
       EXISTS (SELECT 1 FROM credit_ledger e WHERE e.grant_id = s.id AND e.kind = 'expire') AS expired
FROM credit_ledger s
LEFT JOIN LATERAL (
    SELECT SUM(c.credits) AS used FROM credit_ledger c WHERE c.grant_id = s.id AND c.workspace_id = s.workspace_id
) u ON true
WHERE s.workspace_id = $1 AND s.credits > 0 AND s.kind IN ('grant_allowance', 'grant_topup', 'adjust')
  AND (s.expires_at IS NULL OR s.expires_at > $2)
ORDER BY (s.kind <> 'grant_allowance'), s.expires_at NULLS LAST, s.created_at, s.id
`

type ListCreditSourcesParams struct {
	WorkspaceID ids.WorkspaceID
	Now         *time.Time
}

type ListCreditSourcesRow struct {
	ID        uuid.UUID
	Kind      string
	Granted   int32
	ExpiresAt *time.Time
	CreatedAt time.Time
	Plan      *string
	Remaining int32
	Expired   bool
}

// The sources the workspace can use now (not past their expiry) with what is left of each, in the order they are used: the allowance
// first, then the others, earliest expiry first (a source that never expires, the trial's allowance, last of its kind). A source's
// credits left are its own credits plus every row that names it (charges and expiries are negative, refunds positive).
func (q *Queries) ListCreditSources(ctx context.Context, arg ListCreditSourcesParams) ([]ListCreditSourcesRow, error) {
	rows, err := q.db.Query(ctx, listCreditSources, arg.WorkspaceID, arg.Now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListCreditSourcesRow
	for rows.Next() {
		var i ListCreditSourcesRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.Granted,
			&i.ExpiresAt,
			&i.CreatedAt,
			&i.Plan,
			&i.Remaining,
			&i.Expired,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

